// Define la interfaz del Repository
public interface IProductoRepository
{
    IEnumerable<Producto> ObtenerProductos();
}

// Implementa el Repository
public class ProductoRepository : IProductoRepository
{
    // Simula una BD con lista en memoria para poder ejecutar
    private List<Producto> productos = new List<Producto>()
    {
        new Producto { Id = 1, Nombre = "Producto 1" },
        new Producto { Id = 2, Nombre = "Producto 2" },
    };

    public IEnumerable<Producto> ObtenerProductos()
    {
        return productos;
    }
}

// Define la entidad Producto
public class Producto
{
    public int Id { get; set; }
    public string Nombre { get; set; }
}

class Program
{
    static void Main(string[] args)
    {
        ProductoRepository repository = new ProductoRepository();
        var productos = repository.ObtenerProductos();

        foreach (var producto in productos)
        {
            Console.WriteLine(producto.Nombre);
        }
    }
}
